                    { 639, "Estilos de Natación: Dominar al menos tres estilos de natación diferentes, como crol, espalda y braza, demostrando técnica y eficiencia en cada uno.", 104 },
                    { 640, "Rescate Acuático Básico: Aprendo y practico técnicas básicas de rescate acuático, como el nado de rescate, el remolque de una víctima y la realización de una entrada segura al agua para realizar un rescate.", 104 },
                    { 641, "Seguridad Acuática: Conozco y aplico las normas de seguridad en piscinas y entornos acuáticos naturales, incluyendo la identificación de señales de peligro y la comprensión de las reglas de salvavidas.", 104 },
                    { 642, "Participación en una Competencia o Evento de Natación: Participo en una competencia de natación, evento comunitario o demostración de habilidades, aplicando las técnicas aprendidas y reflexionando sobre la experiencia.", 104 },
                    { 643, "Proyecto de Concienciación: Desarrollo un proyecto de concienciación sobre la seguridad acuática para mi grupo o comunidad, como una presentación, un folleto informativo o una campaña de redes sociales, promoviendo prácticas seguras en el agua.", 104 },
                    { 644, "Conocimiento de Textos Sagrados: Aprendo y reflexiono sobre al menos tres pasajes significativos de los textos sagrados de mi fe, explicando su significado y cómo se aplican en la vida diaria.", 105 },
                    { 645, "Participación en Servicios Religiosos: Participo activamente en los servicios religiosos de mi comunidad durante al menos tres meses, contribuyendo de manera significativa en las actividades y ceremonias.", 105 },
                    { 646, "Organización de Actividades de Fe: Organizo y lidero al menos dos actividades relacionadas con mi fe, como estudios bíblicos, grupos de oración, retiros espirituales o eventos de servicio comunitario.", 105 },
                    { 647, "Proyecto de Servicio Comunitario: Desarrollo y ejecuto un proyecto de servicio comunitario que refleje los valores de mi fe, como una campaña de recolección de alimentos, una visita a un hogar de ancianos o una limpieza comunitaria.", 105 },
                    { 648, "Reflexión y Testimonio Personal: Escribo y comparto un testimonio personal sobre mi fe y cómo ha influido en mi vida, presentándolo a mi grupo o comunidad de fe.", 105 },
                    { 649, "Mentoría y Apoyo Espiritual: Actúo como mentor para otros jóvenes en mi comunidad de fe, ofreciendo apoyo espiritual y ayudándolos a crecer en su propio camino de fe.", 105 },
                    { 650, "Historia y Cultura: Investigo y presento sobre al menos tres eventos históricos importantes y tres figuras relevantes de la historia de mi país, explicando su impacto y legado.", 106 },
                    { 651, "Geografía y Recursos Naturales: Aprendo sobre la geografía de mi país, incluyendo sus principales regiones, recursos naturales y ecosistemas, y preparo un mapa destacando estos elementos.", 106 },
                    { 652, "Tradiciones y Costumbres: Conozco y participo en al menos dos tradiciones o costumbres culturales de mi país, como festivales, danzas, o celebraciones, y documento mi experiencia.", 106 },
                    { 653, "Símbolos Nacionales: Investigo sobre los símbolos nacionales de mi país, como la bandera, el escudo y el himno, y explico su significado y origen.", 106 },
                    { 654, "Proyecto Comunitario: Desarrollo y ejecuto un proyecto que beneficie a mi comunidad, como una campaña de limpieza, una actividad educativa sobre la historia local, o un evento cultural.", 106 },
                    { 655, "Promoción del Orgullo Nacional: Creo un cartel, folleto o presentación que promueva el orgullo y conocimiento sobre mi país, y lo comparto con mi grupo, escuela o comunidad.", 106 },
                    { 656, "Conocimiento de Culturas Internacionales: Investigo y presento sobre al menos tres culturas diferentes, describiendo sus tradiciones, costumbres, festivales y formas de vida.", 107 },
                    { 657, "Aprendizaje de Frases Básicas en Otro Idioma: Aprendo y utilizo frases básicas de saludo y cortesía en al menos dos idiomas diferentes al mío.", 107 },
                    { 658, "Correspondencia Internacional:Mantengo correspondencia (por carta o correo electrónico) con un joven de otro país, intercambiando información sobre nuestras vidas, culturas y experiencias.", 107 },
                    { 659, "Participación en una Actividad Multicultural: Participo en una actividad o evento multicultural, como un festival internacional, una feria cultural o una exposición de arte de otro país, y documento mi experiencia.", 107 },
                    { 660, "Proyecto de Promoción de la Paz y la Cooperación: Desarrollo y ejecuto un proyecto que promueva la paz, la cooperación y el entendimiento entre culturas, como una presentación sobre la importancia de la diversidad, un mural colaborativo, o una campaña en redes sociales.", 107 },
                    { 661, "Reflexión sobre la Diversidad Cultural: Escribo una reflexión personal sobre lo que he aprendido acerca de la diversidad cultural y cómo puedo aplicar este conocimiento para promover la comprensión y la cooperación en mi comunidad.", 107 },
                    { 662, "Conocimiento de la Prevención de Incendios: Aprendo sobre las causas comunes de los incendios y las medidas de prevención que pueden tomarse en el hogar y la comunidad para evitar incendios.", 108 },
                    { 663, "Equipos y Herramientas de Bomberos: Conozco los equipos y herramientas básicas utilizadas por los bomberos, como mangueras, extintores, equipo de protección personal, y aprendo cómo funcionan.", 108 },
                    { 664, "Uso de Extintores: Aprendo y demuestro cómo utilizar correctamente diferentes tipos de extintores para apagar fuegos pequeños de acuerdo con su clase (A, B, C, D y K).", 108 },
                    { 665, "Plan de Evacuación: Desarrollo un plan de evacuación para mi hogar o escuela, incluyendo rutas de escape, puntos de reunión y procedimientos en caso de emergencia.", 108 },
                    { 666, "Técnicas Básicas de Primeros Auxilios: Aprendo y practico técnicas básicas de primeros auxilios, incluyendo cómo tratar quemaduras menores, cortes, y cómo realizar reanimación cardiopulmonar (RCP) básica.", 108 },
                    { 667, "Visita a una Estación de Bomberos: Organizo o participo en una visita a una estación de bomberos local, aprendiendo de los profesionales sobre su trabajo diario, los desafíos que enfrentan y las experiencias que tienen.", 108 },
                    { 668, "Conocimiento de Derechos y Deberes Ciudadanos: Investigo y aprendo sobre los derechos y deberes fundamentales de los ciudadanos en mi país, incluyendo la Constitución y leyes relevantes.", 109 },
                    { 669, "Participación en la Comunidad: Participo en al menos dos actividades comunitarias o proyectos de servicio, como campañas de limpieza, programas de ayuda social o eventos comunitarios, y reflexiono sobre mi experiencia.", 109 },
                    { 670, "Sistemas de Gobierno: Aprendo sobre los diferentes niveles y funciones del gobierno en mi país, incluyendo las responsabilidades de los funcionarios públicos y cómo se toman las decisiones que afectan a la comunidad.", 109 },
                    { 671, "Educación Cívica: Organizo o participo en una sesión educativa sobre un tema de interés cívico, como la importancia del voto, el voluntariado o la protección del medio ambiente, y comparto lo aprendido con mi grupo.", 109 },
                    { 672, "Proyecto de Impacto Comunitario: Desarrollo y ejecuto un proyecto que beneficie a mi comunidad, como una campaña de concienciación, una recolección de fondos para una causa local, o una mejora en la infraestructura comunitaria.", 109 },
                    { 673, "Reflexión Personal: Escribo una reflexión personal sobre lo que significa ser un buen ciudadano y cómo puedo aplicar los principios de civismo en mi vida diaria para contribuir positivamente a mi comunidad.", 109 },
                    { 674, "Conocimiento de Seguridad Alimentaria: Aprendo sobre las normas básicas de higiene y seguridad en la cocina, incluyendo el manejo seguro de alimentos y utensilios, y la importancia de mantener una cocina limpia.", 110 },
                    { 675, "Técnicas Básicas de Cocina: Practico al menos cinco técnicas básicas de cocina, como cortar, picar, sofreír, hervir y hornear, y demuestro mi habilidad en cada una.", 110 },
                    { 676, "Preparación de Recetas Simples: Preparo al menos tres recetas simples y nutritivas, como ensaladas, sopas, y platillos principales, siguiendo las instrucciones de manera precisa.", 110 },
                    { 677, "Cocina Internacional: Investigo y preparo un platillo típico de otro país, aprendiendo sobre los ingredientes y técnicas específicas de esa cultura culinaria.", 110 },
                    { 678, "Planificación de Menús: Diseño y preparo un menú completo para una comida, incluyendo entrada, plato principal y postre, teniendo en cuenta el equilibrio nutricional y la presentación.", 110 },
                    { 679, "Proyecto de Cocina Comunitaria: Participo en un proyecto de cocina comunitaria, como una actividad de preparación de alimentos para personas necesitadas, una demostración de cocina en una feria local, o un taller de cocina saludable para niños.", 110 },
                    { 680, "Conocimiento de Normas de Tránsito: Investigo y aprendo sobre las normas de tránsito básicas de mi país, incluyendo señales de tráfico, reglas para peatones, ciclistas y conductores, y el significado de las señales de tráfico más comunes.", 111 },
                    { 681, "Identificación de Señales de Tránsito: Identifico y explico al menos 20 señales de tráfico diferentes, describiendo su significado y la importancia de cada una para la seguridad vial.", 111 },
                    { 682, "Simulación de Situaciones de Tránsito: Participo en simulaciones o ejercicios prácticos que representen situaciones de tránsito comunes, demostrando mi comprensión de cómo aplicar las normas de tránsito en la vida real.", 111 },
                    { 683, "Proyecto de Educación Vial: Desarrollo y ejecuto un proyecto educativo sobre seguridad vial, como una campaña de concienciación, una charla en una escuela o un taller para niños, promoviendo el respeto y la responsabilidad en la vía pública.", 111 },
                    { 684, "Investigación sobre Accidentes de Tránsito: Investigo y presento sobre las causas y consecuencias de los accidentes de tránsito, incluyendo estadísticas locales y estrategias de prevención.", 111 },
                    { 685, "Conocimiento de los Fundamentos del Feng Shui: Aprendo sobre la historia y los principios básicos del Feng Shui, incluyendo el concepto de energía (Qi), los cinco elementos (agua, madera, fuego, tierra y metal) y el bagua.", 112 },
                    { 686, "Mapa Bagua: Aprendo a elaborar un mapa bagua y lo aplico en un espacio de mi elección (como mi habitación, sala de estar o área de estudio), identificando las áreas correspondientes a los diferentes aspectos de la vida (salud, amor, carrera, etc.).", 112 },
                    { 687, "Equilibrio de los Cinco Elementos: Aprendo a equilibrar los cinco elementos en un espacio, utilizando colores, materiales y formas que representen cada elemento, y aplico estos principios en la decoración de una habitación.", 112 },
                    { 688, "Organización y Despeje de Espacios: Practico técnicas de organización y despeje de espacios para mejorar el flujo de energía, eliminando el desorden y reorganizando los objetos para crear un entorno más armonioso.", 112 },
                    { 689, "Creación de un Jardín Feng Shui: Diseño y creo un pequeño jardín Feng Shui, utilizando plantas, agua y otros elementos naturales para promover el equilibrio y la armonía en un espacio exterior o interior.", 112 },
                    { 690, "Planificación y Organización: Aprendo a planificar y organizar las tareas del hogar, incluyendo la creación de un horario semanal para las tareas domésticas y el manejo de un presupuesto básico para gastos del hogar.", 113 },
                    { 691, "Limpieza y Mantenimiento del Hogar: Realizo tareas de limpieza y mantenimiento del hogar, como barrer, trapear, limpiar ventanas, lavar platos y ropa, y organizar espacios de almacenamiento.", 113 },
                    { 692, "Cocina y Nutrición: Planifico, preparo y cocino al menos tres comidas saludables y equilibradas, siguiendo principios básicos de nutrición y seguridad alimentaria.", 113 },
                    { 693, "Primeros Auxilios Domésticos: Aprendo y practico técnicas básicas de primeros auxilios, como tratar quemaduras menores, cortes y heridas, y qué hacer en caso de atragantamiento o desmayos.", 113 },
                    { 694, "Cuidado de la Ropa y del Calzado: Aprendo a cuidar adecuadamente la ropa y el calzado, incluyendo técnicas de lavado, secado, planchado y reparación básica.", 113 },
                    { 695, "Proyecto de Mejora del Hogar: Desarrollo y ejecuto un proyecto que mejore algún aspecto del hogar, como organizar un espacio, decorar una habitación o reparar un mueble, y documento el proceso y el resultado.", 113 },
                    { 696, "Planificación de Excursiones: Aprendo a planificar una excursión al aire libre, incluyendo la selección del lugar, la preparación del itinerario, la lista de equipo necesario y las medidas de seguridad.", 114 },
                    { 697, "Orientación y Navegación: Adquiero habilidades de orientación y navegación, aprendiendo a utilizar mapas, brújulas y GPS, y demuestro estas habilidades en una práctica al aire libre.", 114 },
                    { 698, "Liderazgo de Grupo: Practico técnicas de liderazgo y manejo de grupo, organizando y liderando una actividad al aire libre para mi grupo, asegurándome de mantener la cohesión y la seguridad del grupo.", 114 },
                    { 699, "Primeros Auxilios en la Naturaleza: Aprendo y practico técnicas básicas de primeros auxilios específicas para actividades al aire libre, incluyendo el tratamiento de picaduras, cortes, heridas y manejo de fracturas.", 114 },
                    { 700, "Conocimiento del Entorno Natural: Investigo y presento sobre la flora y fauna local del área donde realizo mis actividades al aire libre, aprendiendo a identificar plantas y animales y a respetar su hábitat.", 114 },
                    { 701, "Evaluación de Riesgos y Seguridad: Conozco y aplico las normas de seguridad y evaluación de riesgos en actividades al aire libre, desarrollando un plan de contingencia para situaciones de emergencia durante una excursión.", 114 },
                    { 702, "Conocimiento del Proceso de Producción: Aprendo sobre el proceso completo de producción de leche, desde el ordeño hasta la pasteurización, y las diferentes etapas involucradas en la obtención de productos lácteos.", 115 },
                    { 703, "Ordeño y Manejo de Animales: Participo en el proceso de ordeño, aprendiendo y practicando las técnicas adecuadas para ordeñar a mano o con equipo mecánico, y el cuidado general de los animales lecheros.", 115 },
                    { 704, "Higiene y Seguridad Alimentaria: Conozco y aplico las normas de higiene y seguridad en la producción de leche, incluyendo la limpieza del equipo de ordeño y las instalaciones, y la prevención de enfermedades.", 115 },
                    { 705, "Elaboración de Productos Lácteos: Preparo al menos dos productos lácteos, como queso, yogur o mantequilla, siguiendo las técnicas tradicionales y modernas de elaboración.", 115 },
                    { 706, "Nutrición y Beneficios de la Leche: Investigo y presento sobre los beneficios nutricionales de la leche y los productos lácteos, y su importancia en una dieta equilibrada.", 115 },
                    { 707, "Visita a una Granja Lechera o Planta de Procesamiento: Organizo o participo en una visita a una granja lechera o una planta de procesamiento de productos lácteos, aprendiendo de los profesionales sobre su trabajo y los desafíos que enfrentan.", 115 },
                    { 708, "Introducción a los Primeros Auxilios: Aprendo sobre la importancia de los primeros auxilios y los principios básicos de cómo actuar en una emergencia, incluyendo la evaluación de la escena y la prioridad de las acciones.", 116 },
                    { 709, "Reanimación Cardiopulmonar (RCP): Aprendo y practico la técnica de RCP en adultos, niños y bebés, incluyendo el uso de un desfibrilador externo automático (DEA) si está disponible.", 116 },
                    { 710, "Tratamiento de Heridas y Hemorragias: Aprendo a limpiar y vendar heridas, detener hemorragias, y aplicar técnicas de primeros auxilios para cortes, raspaduras y heridas punzantes.", 116 },
                    { 711, "Manejo de Fracturas y Lesiones Musculares: Aprendo a inmovilizar fracturas y a tratar esguinces, torceduras y calambres, utilizando materiales disponibles para crear férulas y vendajes.", 116 },
                    { 712, "Tratamiento de Quemaduras y Lesiones por Calor: Aprendo a reconocer y tratar diferentes grados de quemaduras y otras lesiones causadas por el calor, como golpes de calor y agotamiento por calor.", 116 },
                    { 713, "Atención a Víctimas de Asfixia y Shock: Aprendo a realizar maniobras para desobstruir las vías respiratorias en personas asfixiadas y a identificar y tratar a víctimas en estado de shock.", 116 },
                    { 714, "Simulacro de Emergencia: Participo en un simulacro de emergencia donde pongo en práctica todas las habilidades aprendidas, manejando una situación simulada de primeros auxilios de manera efectiva.", 117 },
                    { 715, "Entendimiento de la Paz y Conflicto: Aprendo sobre los conceptos de paz y conflicto, incluyendo las causas comunes de los conflictos y las estrategias para resolverlos de manera pacífica.", 117 },
                    { 716, "Habilidades de Mediación y Resolución de Conflictos: Practico técnicas de mediación y resolución de conflictos, como la escucha activa, la empatía y la negociación, y demuestro mi capacidad para aplicarlas en situaciones simuladas.", 117 },
                    { 717, "Promoción de la Cooperación: Organizo y lidero una actividad que fomente la cooperación y el trabajo en equipo en mi grupo o comunidad, promoviendo valores de respeto y comprensión.", 117 },
                    { 718, "Proyecto de Servicio Comunitario: Desarrollo y ejecuto un proyecto de servicio comunitario que tenga como objetivo la promoción de la paz, como una campaña de concienciación, un evento de diálogo intercultural, o una actividad de voluntariado.", 117 },
                    { 719, "Estudio de Líderes por la Paz: Investigo y presento sobre al menos dos líderes o figuras históricas que hayan trabajado por la paz, describiendo sus contribuciones y el impacto de su trabajo.", 117 },
                    { 720, "Reflexión Personal: Escribo una reflexión personal sobre la importancia de la paz y cómo puedo aplicar las habilidades y conocimientos adquiridos para promover la paz en mi vida diaria y en mi comunidad.", 117 },
                    { 721, "Importancia de la Salud Mental: Aprendo sobre la importancia de la salud mental y el bienestar emocional.", 118 },
                    { 722, "Técnicas de Manejo del Estrés: Practico técnicas de manejo del estrés y la ansiedad (meditación, respiración, ejercicio, etc.).", 118 },
                    { 723, "Plan Personal de Bienestar: Creo un plan personal de bienestar y lo sigo durante un mes.", 118 },
                    { 724, "Participación en Talleres: Participo en un taller o curso sobre salud mental.", 118 },
                    { 725, "Recursos de Apoyo Emocional: Aprendo sobre los recursos disponibles para apoyo emocional y salud mental.", 118 },
                    { 726, "Campaña de Concienciación: Desarrollar una campaña de concienciación sobre salud mental en tu escuela o comunidad.", 118 },
                    { 727, "Natación y Resistencia: Demuestro mi habilidad para nadar al menos 100 metros sin parar, utilizando diferentes estilos de natación como crol, braza y espalda.", 119 },
                    { 728, "Técnicas de Rescate Acuático: Aprendo y practico técnicas básicas de rescate acuático, incluyendo el nado de rescate, el remolque de una víctima y el uso de dispositivos de flotación.", 119 },
                    { 729, "Primeros Auxilios y RCP: Aprendo y demuestro conocimientos en primeros auxilios y reanimación cardiopulmonar (RCP) específicos para víctimas de accidentes acuáticos.", 119 },
                    { 730, "Evaluación de Riesgos y Prevención de Accidentes: Conozco y aplico las normas de seguridad en entornos acuáticos, identificando peligros potenciales y desarrollando estrategias para prevenir accidentes.", 119 },
                    { 731, "Simulación de Emergencias: Participo en simulaciones de emergencias acuáticas, donde aplico todas las habilidades aprendidas en situaciones simuladas de rescate y primeros auxilios.", 119 },
                    { 732, "Servicio Comunitario: Organizo o participo en una actividad de promoción de la seguridad acuática en mi comunidad, como una charla educativa, una campaña de concienciación o una demostración de rescate.", 119 },
                    { 733, "Habilidades de Observación: Aprendo y practico técnicas de observación, incluyendo el uso de binoculares y cámaras, y la identificación de señales y rastros de animales en su hábitat natural.", 120 },
                    { 734, "Técnicas de Sigilo: Practico técnicas de sigilo para moverme sin ser detectado en diferentes tipos de terreno, aprendiendo a caminar en silencio, a usar la cobertura natural y a evitar dejar rastros.", 120 },
                    { 735, "Identificación de Flora y Fauna: Investigo y aprendo a identificar al menos diez especies de plantas y diez especies de animales locales, comprendiendo su comportamiento, hábitat y el papel que desempeñan en el ecosistema.", 120 },
                    { 736, "Construcción de Refugios Naturales: Construyo un refugio temporal utilizando materiales naturales y técnicas de bajo impacto ambiental, asegurándome de dejar el menor rastro posible.", 120 },
                    { 737, "Proyecto de Conservación: Desarrollo y participo en un proyecto de conservación de la naturaleza, como la recolección de basura en un área natural, la plantación de árboles o la restauración de hábitats.", 120 },
                    { 738, "Jornadas de Observación: Realizo al menos dos jornadas de observación en diferentes entornos naturales, documentando mis observaciones y reflexionando sobre la importancia de la conservación y el respeto por la vida silvestre.", 120 },
                    { 739, "Conocimiento de los Componentes del Acuario: Aprendo sobre los diferentes componentes de un acuario, incluyendo el tanque, el sistema de filtración, la iluminación, el calentador y los sustratos, y su importancia para mantener un ambiente saludable.", 121 },
                    { 740, "Selección y Cuidado de Peces: Investigo y elijo al menos cinco especies de peces adecuadas para un acuario doméstico, aprendiendo sobre sus necesidades específicas de alimentación, temperatura y comportamiento.", 121 },
                    { 741, "Montaje y Mantenimiento del Acuario: Participo en el montaje de un acuario, incluyendo la instalación del equipo necesario, la adición de agua tratada y el ciclo del tanque antes de introducir los peces.", 121 },
                    { 742, "Alimentación y Salud de los Peces: Aprendo a alimentar adecuadamente a los peces, incluyendo la selección de alimentos balanceados y la identificación y tratamiento de enfermedades comunes en los peces de acuario.", 121 },
                    { 743, "Control de Calidad del Agua: Aprendo a realizar pruebas de calidad del agua para medir parámetros como pH, amoníaco, nitritos y nitratos, y a ajustar estos niveles para mantener un ambiente saludable para los peces.", 121 },
                    { 744, "Conocimiento de Especies Avícolas: Aprendo sobre al menos tres especies de aves de corral, como pollos, patos y codornices, incluyendo sus características, necesidades y beneficios de cada una.", 121 },
                    { 745, "Diseño y Mantenimiento de Gallineros: Diseño y participo en la construcción o mantenimiento de un gallinero, asegurándome de que proporcione un ambiente seguro y cómodo para las aves, incluyendo la disposición adecuada de espacio, perchas y nidos.", 122 },
                    { 746, "Alimentación y Nutrición: Aprendo sobre las necesidades alimenticias de las aves de corral y preparo un plan de alimentación balanceado, asegurando que reciban los nutrientes necesarios para su salud y productividad.", 122 },
                    { 747, "Salud y Cuidado de las Aves: Identifico y aprendo a tratar enfermedades comunes en las aves de corral, y practico técnicas de cuidado preventivo, como la vacunación y el manejo adecuado del entorno.", 122 },
                    { 748, "Producción de Huevos y Carne: Investigo y explico el proceso de producción de huevos y carne, incluyendo la recolección, almacenamiento y procesamiento adecuado, y la importancia de la higiene en cada etapa.", 122 },
                    { 749, "Conocimiento de Plantas: Investigo y aprendo sobre al menos diez especies de plantas, incluyendo sus características, hábitats y usos. Realizo un herbario o un álbum de fotos documentando estas plantas.", 123 },
                    { 750, "Identificación y Clasificación: Aprendo a identificar y clasificar plantas utilizando claves de identificación y libros de referencia, reconociendo las principales familias y géneros.", 123 },
                    { 751, "Cultivo y Cuidado de Plantas: Practico técnicas de cultivo, incluyendo la siembra, trasplante, riego y fertilización, cultivando al menos cinco tipos de plantas diferentes en un jardín, macetas o un huerto escolar.", 123 },
                    { 752, "Conservación de la Flora: Investigo sobre la importancia de la conservación de las plantas y participo en un proyecto de conservación, como la reforestación, la creación de un jardín botánico escolar o la promoción de plantas nativas en la comunidad.", 123 },
                    { 753, "Enfermedades y Plagas: Aprendo a identificar y manejar enfermedades y plagas comunes en las plantas, utilizando métodos ecológicos y sostenibles para su control.", 123 },
                    { 754, "Proyecto Educativo sobre Botánica: Desarrollo y presento un proyecto educativo sobre la importancia de las plantas, sus beneficios ecológicos y su conservación, dirigiéndome a mi grupo, escuela o comunidad.", 123 },
                    { 755, "Conocimiento de Materiales y Herramientas: Aprendo sobre los diferentes tipos de cuerdas y sus usos específicos, así como sobre las herramientas básicas utilizadas en cabuyería, como la soga y el mosquetón.", 124 },
                    { 756, "Nudos Básicos: Practico y demuestro la habilidad para realizar al menos diez nudos básicos, incluyendo el nudo llano, el nudo de ocho, el nudo de escota, el nudo de as de guía y el nudo de ballestrinque.", 124 },
                    { 757, "Amarres y Encordados: Aprendo a realizar al menos cinco tipos de amarres y encordados, como el amarre cuadrado, el amarre diagonal, el amarre de trípode y el encordado de paracaídas, aplicándolos en situaciones prácticas.", 124 },
                    { 758, "Aplicaciones Prácticas: Demuestro la aplicación de nudos y amarres en al menos tres situaciones prácticas, como la construcción de una tienda de campaña, la creación de una camilla improvisada o la instalación de una línea de vida.", 124 },
                    { 759, "Mantenimiento y Seguridad: Conozco y practico el mantenimiento adecuado de las cuerdas y herramientas de cabuyería, así como las normas de seguridad necesarias para evitar accidentes y asegurar la durabilidad del equipo.", 124 },
                    { 760, "Proyecto de Cabuyería: Desarrollo y ejecuto un proyecto que involucre el uso de nudos y amarres, como la construcción de una estructura temporal, una actividad de escalada o una demostración educativa para mi grupo, escuela o comunidad.", 124 },
                    { 761, "Planificación de una Acampada: Aprendo a planificar una acampada, incluyendo la selección del lugar, la preparación del equipo necesario y la elaboración de un itinerario que contemple actividades y medidas de seguridad.", 125 },
                    { 762, "Montaje y Desmontaje de Tiendas de Campaña: Practico el montaje y desmontaje de diferentes tipos de tiendas de campaña, asegurándome de que estén correctamente instaladas y protegidas contra el clima.", 125 },
                    { 763, "Construcción de Refugios Naturales: Aprendo a construir refugios temporales utilizando materiales naturales disponibles en el entorno, garantizando que sean seguros y funcionales.", 125 },
                    { 764, "Cocina al Aire Libre: Preparo al menos tres comidas utilizando métodos de cocina al aire libre, como la fogata, el hornillo portátil o la parrilla, siguiendo principios de seguridad alimentaria y ecológica.", 125 },
                    { 765, "Orientación y Navegación: Demuestro habilidades de orientación y navegación en la naturaleza, utilizando mapas, brújulas y técnicas de orientación natural para planificar y seguir una ruta.", 125 },
                    { 766, "Cuidado y Conservación del Entorno Natural: Practico principios de mínimo impacto ambiental, como dejar sin rastro, gestión de residuos y respeto por la flora y fauna local, contribuyendo a la conservación del entorno natural.", 125 },
                    { 767, "Conocimiento de Materiales y Herramientas: Aprendo sobre los diferentes tipos de materiales y herramientas utilizados en las construcciones pioneras, incluyendo maderas, cuerdas y herramientas manuales.", 126 },
                    { 768, "Nudos y Amarres Básicos: Practico y demuestro la habilidad para realizar al menos cinco nudos y amarres esenciales, como el nudo llano, el nudo de as de guía, el nudo de ballestrinque, el amarre cuadrado y el amarre diagonal.", 126 },
                    { 769, "Diseño y Planificación de Proyectos: Aprendo a diseñar y planificar un proyecto de construcción pionera, incluyendo la creación de planos y la lista de materiales necesarios.", 126 },
                    { 770, "Construcción de Estructuras Básicas: Participo en la construcción de al menos tres estructuras pioneras básicas, como un trípode, una mesa de campo, y una torre de observación, utilizando técnicas adecuadas y seguras.", 126 },
                    { 771, "Mantenimiento y Seguridad en Construcciones: Conozco y practico las normas de seguridad en la construcción de estructuras pioneras, incluyendo el mantenimiento adecuado de las herramientas y la supervisión de las construcciones para garantizar su estabilidad y seguridad.", 126 },
                    { 772, "Proyecto de Construcción Avanzada: Desarrollo y ejecuto un proyecto de construcción pionera más avanzado, como un puente colgante, una cocina de campamento o un refugio elevado, demostrando todas las habilidades adquiridas y documentando el proceso y los resultados.", 126 },
                    { 773, "Conocimiento de Ecosistemas y Biodiversidad: Investigo y aprendo sobre al menos tres ecosistemas diferentes y su biodiversidad, incluyendo los animales y plantas que los habitan, y la importancia de cada uno en el equilibrio ecológico.", 127 },
                    { 774, "Reducción y Manejo de Residuos: Practico y demuestro técnicas de reducción, reutilización y reciclaje de residuos en mi hogar, escuela o comunidad, explicando cómo estas acciones ayudan a conservar el medio ambiente.", 127 },
                    { 775, "Proyecto de Conservación de la Naturaleza: Desarrollo y participo en un proyecto de conservación, como la reforestación de un área, la limpieza de un río o playa, o la creación de un jardín de plantas nativas.", 127 },
                    { 776, "Educación Ambiental: Organizo y llevo a cabo una actividad educativa sobre la importancia de la conservación, como una presentación, un taller o una campaña de concienciación en mi comunidad.", 127 },
                    { 777, "Estudio de Especies en Peligro: Investigo y presento sobre al menos dos especies en peligro de extinción, describiendo las amenazas que enfrentan y las acciones que se pueden tomar para su protección.", 127 },
                    { 778, "Conservación del Agua y la Energía: Aprendo y aplico técnicas para conservar agua y energía en mi vida diaria, como el uso de dispositivos de bajo consumo, la implementación de prácticas de ahorro de agua y la promoción de energías renovables.", 127 },
                    { 779, "Conocimiento de los Insectos: Aprendo sobre la clasificación y las características básicas de los insectos, incluyendo las diferencias entre órdenes y familias, y su ciclo de vida.", 128 },
                    { 780, "Colección y Observación de Insectos: Recolecto y observo al menos diez especies diferentes de insectos, documentando sus características y comportamientos, y creando un diario de campo con mis observaciones.", 128 },
                    { 781, "Identificación de Especies: Utilizo guías de campo y claves de identificación para identificar correctamente al menos cinco especies de insectos, describiendo sus características distintivas y su hábitat.", 128 },
                    { 782, "Estudio de un Ecosistema Local: Realizo un estudio de los insectos en un ecosistema local, observando su diversidad y el papel que juegan en el equilibrio ecológico, y presento mis hallazgos a mi grupo o comunidad.", 128 },
                    { 783, "Impacto de los Insectos en la Agricultura y la Salud: Investigo y presento sobre el impacto de los insectos en la agricultura, la salud humana y el medio ambiente, incluyendo tanto los beneficios (como la polinización) como las amenazas (como plagas y vectores de enfermedades).", 128 },
                    { 784, "Proyecto de Conservación de Insectos: Desarrollo y participo en un proyecto de conservación que beneficie a los insectos, como la creación de un jardín de polinizadores, la instalación de hoteles de insectos o la promoción de prácticas agrícolas sostenibles.", 128 },
                    { 785, "Planificación de Excursiones: Aprendo a planificar una excursión, incluyendo la selección de la ruta, la preparación del equipo necesario, la consideración del clima y la elaboración de un itinerario detallado.", 129 },
                    { 786, "Orientación y Navegación: Demuestro habilidades de orientación y navegación utilizando mapas, brújulas y técnicas de orientación natural para seguir una ruta y no perderme en el camino.", 129 },
                    { 787, "Seguridad al Aire Libre: Conozco y aplico las normas de seguridad al aire libre, incluyendo la identificación de riesgos, la prevención de accidentes y la actuación en caso de emergencia.", 129 },
                    { 788, "Cuidado y Conservación del Entorno Natural: Practico principios de mínimo impacto ambiental, como dejar sin rastro, gestión de residuos y respeto por la flora y fauna local, contribuyendo a la conservación del entorno natural.", 129 },
                    { 789, "Participación en Excursiones: Participo en al menos tres excursiones, cada una de un día completo, aplicando todas las habilidades aprendidas y reflejando sobre la experiencia.", 129 },
                    { 790, "Proyecto de Servicio Ambiental: Desarrollo y ejecuto un proyecto de servicio ambiental relacionado con el senderismo, como la limpieza de senderos, la instalación de señalización o la promoción del senderismo responsable en mi comunidad.", 129 },
                    { 791, "Conocimiento de los Bosques: Aprendo sobre los diferentes tipos de bosques, sus características, la biodiversidad que albergan y su importancia ecológica y económica.", 130 },
                    { 792, "Identificación de Árboles y Plantas: Identifico y describo al menos diez especies de árboles y plantas comunes en los bosques de mi región, incluyendo sus características y su papel en el ecosistema.", 130 },
                    { 793, "Reforestación y Plantación de Árboles: Participo en actividades de reforestación, aprendiendo y practicando técnicas de plantación de árboles y el cuidado de las plántulas.", 130 },
                    { 794, "Prevención de Incendios Forestales: Aprendo sobre las causas y consecuencias de los incendios forestales, y practico medidas de prevención y respuesta ante incendios, incluyendo la creación de cortafuegos y el uso de herramientas básicas de extinción.", 130 },
                    { 795, "Gestión Sostenible de Recursos Forestales: Investigo y presento sobre prácticas de gestión sostenible de los recursos forestales, como el manejo de madera, la conservación de la biodiversidad y la promoción de productos forestales no maderables.", 130 },
                    { 796, "Proyecto de Conservación Forestal: Desarrollo y participo en un proyecto de conservación forestal en mi comunidad, como la creación de senderos educativos, la instalación de señalización para la protección de áreas sensibles o la organización de campañas de concienciación", 130 },
                    { 797, "Conocimiento de la Vida Silvestre: Aprendo sobre la importancia de la vida silvestre en los ecosistemas y las principales amenazas que enfrentan, como la pérdida de hábitat, la caza furtiva y el cambio climático.", 131 },
                    { 798, "Identificación de Especies Locales: Identifico y estudio al menos diez especies de fauna local, incluyendo sus características, comportamiento y el papel que desempeñan en el ecosistema.", 131 },
                    { 799, "Observación y Registro de Vida Silvestre: Realizo observaciones de campo, documentando la presencia y comportamiento de la fauna local en un diario de campo, incluyendo fotografías y descripciones detalladas.", 131 },
                    { 800, "Proyectos de Conservación: Participo en al menos un proyecto de conservación de vida silvestre, como la restauración de hábitats, la creación de corredores de vida silvestre o la instalación de refugios y cajas nido.", 131 },
                    { 801, "Educación y Concienciación: Desarrollo y llevo a cabo una actividad educativa sobre la importancia de la conservación de la vida silvestre, como una presentación, un taller o una campaña de concienciación en mi comunidad.", 131 },
                    { 802, "Conocimiento de Plantas y Suelos: Aprendo sobre los diferentes tipos de plantas hortícolas y ornamentales, así como sobre las características de los suelos y su preparación para el cultivo.", 132 },
                    { 803, "Preparación y Siembra: Preparo un área de cultivo, selecciono las semillas o plántulas adecuadas y realizo la siembra siguiendo prácticas hortícolas recomendadas.", 132 },
                    { 804, "Cuidado y Mantenimiento de Cultivos: Aprendo y aplico técnicas de riego, fertilización, control de malezas y protección contra plagas y enfermedades, asegurando el crecimiento saludable de las plantas.", 132 },
                    { 805, "Técnicas de Propagación: Practico al menos dos métodos de propagación de plantas, como el esqueje, la división o el injerto, y explico su importancia en la horticultura.", 132 },
                    { 806, "Cosecha y Conservación de Productos: Cosecho y conservo al menos tres tipos de cultivos, aprendiendo métodos de almacenamiento y preservación para mantener la calidad de los productos hortícolas.", 132 },
                    { 807, "Proyecto de Horticultura Comunitaria: Desarrollo y participo en un proyecto de horticultura en mi comunidad, como la creación de un huerto escolar, la implementación de un jardín comunitario o la promoción de prácticas de horticultura sostenible.", 132 },
                    { 808, "Conocimiento de Plantas de Jardín: Aprendo sobre al menos diez especies de plantas ornamentales comunes en los jardines, incluyendo sus características, necesidades de crecimiento y cuidados específicos.", 133 },
                    { 809, "Diseño y Planificación de Jardines: Diseño un jardín ornamental, considerando la selección de plantas, la disposición de las áreas de plantación y la estética general del espacio.", 133 },
                    { 810, "Preparación del Suelo y Siembra: Preparo el suelo adecuadamente para la siembra, aprendiendo sobre enmiendas del suelo, compostaje y técnicas de siembra directa y trasplante de plántulas.", 133 },
                    { 811, "Cuidado y Mantenimiento del Jardín: Practico técnicas de riego, fertilización, poda y control de plagas y enfermedades, asegurando el crecimiento saludable de las plantas en mi jardín.", 133 },
                    { 812, "Propagación de Plantas: Realizo al menos dos métodos de propagación de plantas, como esquejes, acodos o división, y explico la importancia de cada método en la jardinería.", 133 },
                    { 813, "Proyecto de Jardinería Comunitaria: Desarrollo y participo en un proyecto de jardinería en mi comunidad, como la creación de un jardín escolar, la implementación de un jardín comunitario o la promoción de prácticas de jardinería sostenible.", 133 },
                    { 814, "Conocimiento de Materiales Reciclables: Aprendo sobre los diferentes tipos de materiales reciclables, como papel, cartón, vidrio, plásticos, metales y residuos orgánicos, y cómo se clasifican y procesan para su reciclaje.", 134 },
                    { 815, "Clasificación de Residuos: Practico la clasificación de residuos en mi hogar, escuela o comunidad, separando correctamente los materiales reciclables de los no reciclables y aprendiendo sobre los símbolos de reciclaje.", 134 },
                    { 816, "Creación de un Sistema de Reciclaje: Diseño e implemento un sistema de reciclaje en mi hogar, escuela o comunidad, incluyendo la instalación de contenedores de reciclaje claramente etiquetados y la educación a otros sobre su uso adecuado.", 134 },
                    { 817, "Reutilización y Reducción de Residuos: Desarrollo al menos dos proyectos de reutilización creativa de materiales reciclables, como la creación de artesanías, muebles o juguetes, y promuevo prácticas de reducción de residuos en mi entorno.", 134 },
                    { 818, "Visita a una Planta de Reciclaje: Organizo o participo en una visita a una planta de reciclaje local, aprendiendo sobre el proceso de reciclaje, desde la recolección hasta la transformación de materiales reciclables en nuevos productos.", 134 },
                    { 819, "Habilidades de Observación: Aprendo y practico técnicas de observación detallada, utilizando binoculares, lupas y cámaras para captar imágenes y detalles de la naturaleza.", 135 },
                    { 820, "Registro de Observaciones: Mantengo un diario de campo donde documento mis observaciones sobre al menos diez especies de plantas y diez especies de animales, incluyendo descripciones, comportamientos y hábitats.", 135 },
                    { 821, "Identificación de Especies: Utilizo guías de campo y claves de identificación para identificar correctamente al menos cinco especies de plantas y cinco especies de animales, describiendo sus características distintivas.", 135 },
                    { 822, "Realización de Excursiones de Observación: Participo en al menos tres excursiones de observación en diferentes entornos naturales, aplicando todas las habilidades aprendidas y reflexionando sobre las experiencias.", 135 },
                    { 823, "Proyecto de Conservación: Desarrollo y participo en un proyecto de conservación relacionado con la observación de la naturaleza, como la creación de un sendero educativo, la instalación de cajas nido o la promoción de la biodiversidad local.", 135 },
                    { 824, "Presentación de Hallazgos: Organizo y presento una exposición o una charla sobre mis observaciones y descubrimientos a mi grupo, escuela o comunidad, compartiendo lo aprendido y promoviendo la conservación de la naturaleza.", 135 },
                    { 825, "Conocimiento de Aves: Aprendo sobre las características generales de las aves, incluyendo su anatomía, comportamiento, y el papel que desempeñan en el ecosistema.", 136 },
                    { 826, "Identificación de Especies de Aves: Utilizo guías de campo y binoculares para identificar correctamente al menos diez especies de aves en mi área local, describiendo sus características, cantos y comportamientos.", 136 },
                    { 827, "Registro de Observaciones: Mantengo un diario de campo donde documento mis observaciones sobre las aves, incluyendo fechas, lugares, descripciones detalladas y comportamientos observados.", 136 },
                    { 828, "Construcción de Refugios para Aves: Aprendo a construir y coloco al menos dos cajas nido o comederos para aves, contribuyendo a su bienestar y observando su uso por las aves locales.", 136 },
                    { 829, "Participación en Programas de Conservación: Participo en al menos un programa de conservación de aves, como censos de aves, proyectos de monitoreo o campañas de protección de hábitats.", 136 },
                    { 830, "Educación y Concienciación: Desarrollo y llevo a cabo una actividad educativa sobre la importancia de las aves y su conservación, como una presentación, un taller o una campaña en mi comunidad.", 136 },
                    { 831, "Conocimiento de Especies de Peces: Aprendo sobre al menos cinco especies de peces comunes en las aguas locales, incluyendo sus características, hábitats y comportamientos.", 137 },
                    { 832, "Equipo y Técnicas de Pesca: Aprendo sobre el equipo básico de pesca, incluyendo cañas, anzuelos, carretes y cebos, y practico al menos dos técnicas de pesca, como la pesca con mosca y la pesca con señuelo.", 137 },
                    { 833, "Regulaciones y Conservación: Investigo y explico las regulaciones locales de pesca, incluyendo las tallas mínimas y las temporadas de veda, y discuto la importancia de la pesca sostenible y la conservación de los recursos acuáticos.", 137 },
                    { 834, "Seguridad en la Pesca: Conozco y practico las normas de seguridad durante la pesca, incluyendo el uso de chalecos salvavidas, la manipulación segura del equipo y la prevención de accidentes en el agua.", 137 },
                    { 835, "Limpieza y Cuidado del Pescado: Aprendo y demuestro cómo limpiar y preparar adecuadamente el pescado capturado para el consumo, asegurándome de seguir prácticas higiénicas y responsables.", 137 },
                    { 836, "Proyecto de Conservación Acuática: Desarrollo y participo en un proyecto de conservación relacionado con los ecosistemas acuáticos, como la limpieza de ríos o lagos, la reforestación de riberas o la promoción de prácticas de pesca sostenible en mi comunidad.", 137 },
                    { 837, "Lectura de Mapas: Aprendo a leer e interpretar diferentes tipos de mapas, incluyendo topográficos, de carreteras y de senderos, identificando símbolos, escalas y coordenadas.", 138 },
                    { 838, "Uso de la Brújula: Demuestro habilidad en el uso de la brújula para determinar direcciones, tomar rumbos y seguir trayectorias en el campo.", 138 },
                    { 839, "Orientación con Técnicas Naturales: Aprendo y practico al menos tres técnicas de orientación natural, como la observación del sol, las estrellas y la vegetación, para encontrar direcciones sin el uso de mapas o brújulas.", 138 },
                    { 840, "Planificación de una Ruta: Planifico y ejecuto una ruta de orientación, utilizando un mapa y una brújula para navegar por un área desconocida, asegurándome de tener en cuenta la seguridad y las condiciones del terreno.", 138 },
                    { 841, "Resolución de Problemas de Navegación: Participo en actividades o simulaciones donde debo resolver problemas de navegación, como desviaciones de ruta o la identificación de puntos de referencia en el terreno.", 138 },
                    { 842, "Proyecto de Enseñanza: Desarrollo y llevo a cabo una actividad educativa para enseñar a otros sobre las habilidades de orientación, como un taller práctico o una demostración en un evento comunitario.", 138 },
                    { 843, "Conocimiento de Equipos de Transmisión: Aprendo sobre los diferentes tipos de equipos de transmisión, como radios de banda ciudadana (CB), radios de alta frecuencia (HF) y radios de muy alta frecuencia (VHF), y sus aplicaciones.", 139 },
                    { 844, "Operación Básica de Radios: Demuestro cómo operar correctamente un radio de dos vías, incluyendo encendido/ apagado, ajuste de frecuencia, uso de canales y transmisión de mensajes.", 139 },
                    { 845, "Código Fonético y Procedimientos de Comunicación: Aprendo y practico el uso del alfabeto fonético internacional y los procedimientos de comunicación estándar para asegurar claridad y precisión en los mensajes.", 139 },
                    { 846, "Configuración y Mantenimiento de Equipos: Aprendo a configurar y mantener los equipos de transmisión, incluyendo la instalación de antenas, el ajuste de los equipos y el cuidado de los dispositivos para garantizar un funcionamiento óptimo.", 139 },
                    { 847, "Simulaciones de Comunicación de Emergencia: Participo en simulaciones donde uso equipos de transmisión para coordinar operaciones de emergencia, practicando habilidades de comunicación en situaciones críticas.", 139 },
                    { 848, "Explica lo básico acerca de la historia del teatro, dónde y cuánto se inició y cuándo fue su apogeo.", 140 },
