                    { 866, "Explica la importancia del balanceado, centrado y diedro del ala.", 141 },
                    { 867, "Demuestra que conoces todas las categorías de aeromodelos y las piruetas más importantes en vuelos radiocontrolados.", 141 },
                    { 868, "Describe las herramientas necesarias para la construcción de aeromodelos.", 141 },
                    { 869, "Diseña y construye un modelo de pequeñas dimensiones (Fuselaje balsa 4 cm, ala balsa 2 cm, envergadura 25 cm, largo de fuselaje 25 cm, estabilizador 8 cm.", 141 },
                    { 870, "Investiga y explica como esta conformado el suelo.", 142 },
                    { 871, "Explica como se debe de conservar y preparar el suelo para la agricultura.", 142 },
                    { 872, "Averigua y explica cuales son las herramientas y maquinarias, que se usan para agricultura.", 142 },
                    { 873, "Infórmate  sobre  diferentes tipos de ganados existentes en tu Departamento como también de las especies nativas del mismo.", 142 },
                    { 874, "Explica cual es la importancia de la rotación de cultivos y la eliminación de plagas, de forma no contaminantes.", 142 },
                    { 875, "Explica los tipos y técnicas de cultivo que se utilizan en tu Departamento.", 142 },
                    { 876, "Explica que es la agricultura orgánica", 142 },
                    { 877, "Prepara  para  toda  tu  unidad,  una  exposición  con  todo  lo  investigado anteriormente.", 142 },
                    { 878, "Fabrica abono con elementos no contaminantes.", 142 },
                    { 879, "Realiza una exposición para todo el grupo de la importancia de la agricultura para el país", 142 },
                    { 880, "Organiza junto a tu Unidad, una salida a una finca o hacienda y colaboren en la reparación de cercas, alimentación de animales, etc.", 142 },
                    { 881, "Prepara un pedazo de tierra, para su cultivo. En ella: Ara, siembra, cosecha, empaca y transporta lo cultivado en el tiempo adecuado.", 142 },
