                    { 887, "Conoce las reglas internacionales de una partida de ajedrez y de un torneo.", 143 },
                    { 888, "Conoce cinco defensas diferentes.", 143 },
                    { 889, "Prepara  para  toda  tu  unidad,  una  exposición  con  todo  lo  investigado anteriormente", 143 },
