                    { 891, "Usa correctamente el reloj de juego.", 143 },
                    { 892, "Organiza un torneo en tu unidad o grupo.", 143 },
                    { 893, "Participa en uno o más torneos.", 143 },
                    { 894, "Investiga y explica los niveles de analfabetismo en el país y en tu departamento.", 144 },
                    { 895, "Investiga y explica si hay alguna institución dedicada a la alfabetización en tu departamento o ciudad y contáctala.", 144 },
                    { 896, "Capacítate como alfabetizador en la institución correspondiente.", 144 },
